// backend_url.dart
import 'dart:convert';
import 'package:http/http.dart' as http;
import 'api_cache.dart';

/// Central backend API URL configuration.
/// - For Android Emulator local testing: 'http://10.0.2.2:8000'
/// - For Physical Device (same Wi-Fi): 'http://<YOUR_LOCAL_IP>:8000'
/// - For Deployed Production: 'https://pollutionviz-3hta.onrender.com'
const String baseURL = 'http://localhost:8000'; // local dev (was https://pollutionviz-backend-services.onrender.com)
/// Scenario presets and citizen actions are generated by an LLM on the backend
/// and are not cached there yet, so they can legitimately take 30s+.
const Duration _llmTimeout = Duration(seconds: 90);
// NOTE: there is intentionally no default location here. Callers must pass the
// user's resolved location (see location_service.dart).

// ==========================================
// Dashboard & Trends Routes
// ==========================================

String dashboardCacheKey(double lat, double lon) =>
    ApiCache.coordKey('dashboard', lat, lon);

/// Last successful [fetchDashboardData] result for this spot, if any.
Future<CachedJson?> loadCachedDashboard({
  required double lat,
  required double lon,
}) => ApiCache.load(dashboardCacheKey(lat, lon));

/// GET /get_location?lat={lat}&lon={lon}
/// Fetches current air pollution, weather, and reverse-geocoded location data.
Future<Map<String, dynamic>?> fetchDashboardData({
  required double lat,
  required double lon,
}) async {
  try {
    final uri = Uri.parse('$baseURL/get_location?lat=$lat&lon=$lon');
    final response = await http.get(uri);

    if (response.statusCode == 200) {
      final jsonData = json.decode(response.body);
      Map<String, dynamic>? result;
      if (jsonData is Map<String, dynamic> && jsonData.containsKey('data')) {
        result = jsonData['data'] as Map<String, dynamic>;
      } else {
        result = jsonData as Map<String, dynamic>?;
      }
      if (result != null) {
        // Fire and forget: the next launch can draw this immediately.
        ApiCache.save(dashboardCacheKey(lat, lon), result);
      }
      return result;
    } else {
      throw Exception('Failed to load dashboard data (${response.statusCode}): ${response.body}');
    }
  } catch (e) {
    print('API Error (fetchDashboardData): $e');
    return null;
  }
}

String trendsCacheKey(double lat, double lon, String range) =>
    ApiCache.coordKey('trends-$range', lat, lon);

/// Last successful [fetchTrendsData] result for this spot and range, if any.
Future<CachedJson?> loadCachedTrends({
  required double lat,
  required double lon,
  required String range,
}) => ApiCache.load(trendsCacheKey(lat, lon, range));

/// GET /get_trends?lat={lat}&lon={lon}&range={range}
/// Fetches historical and forecast pollution trends (weekly, monthly, yearly).
Future<Map<String, dynamic>?> fetchTrendsData({
  required double lat,
  required double lon,
  String range = "weekly",
}) async {
  try {
    final uri = Uri.parse('$baseURL/get_trends?lat=$lat&lon=$lon&range=$range');
    final response = await http.get(uri);

    if (response.statusCode == 200) {
      final jsonData = json.decode(response.body) as Map<String, dynamic>;
      ApiCache.save(trendsCacheKey(lat, lon, range), jsonData);
      return jsonData;
    } else {
      throw Exception('Failed to load trends data (${response.statusCode}): ${response.body}');
    }
  } catch (e) {
    print('API Error (fetchTrendsData): $e');
    return null;
  }
}

// ==========================================
// Scenarios & Citizen Actions Routes
// ==========================================

/// Last successful scenario presets for this spot (the call is a slow LLM one).
Future<List<dynamic>?> loadCachedScenarioPresets({
  required double lat,
  required double lon,
}) async {
  final c = await ApiCache.load(ApiCache.coordKey('presets', lat, lon));
  final list = c?.data['list'];
  return list is List ? list : null;
}

/// Last successful citizen actions for this spot.
Future<Map<String, dynamic>?> loadCachedCitizenActions({
  required double lat,
  required double lon,
}) async =>
    (await ApiCache.load(ApiCache.coordKey('actions', lat, lon)))?.data;

/// GET /get_scenario_presets?lat={lat}&lon={lon}
/// Fetches simulated negative future scenarios for the given coordinates.
Future<List<dynamic>?> fetchScenarioPresets({
  required double lat,
  required double lon,
}) async {
  try {
    final uri = Uri.parse('$baseURL/get_scenario_presets?lat=$lat&lon=$lon');
    final response = await http.get(uri).timeout(_llmTimeout);

    if (response.statusCode == 200) {
      final data = json.decode(response.body);
      if (data is List) {
        ApiCache.save(ApiCache.coordKey('presets', lat, lon), {'list': data});
        return data;
      } else {
        throw Exception('Expected List response, got ${data.runtimeType}');
      }
    } else {
      throw Exception('Failed to load scenario presets (${response.statusCode}): ${response.body}');
    }
  } catch (e) {
    print('API Error (fetchScenarioPresets): $e');
    rethrow;
  }
}

/// POST /citizen_actions?lat={lat}&lon={lon}
/// Fetches recommended practical actions (do, dont, minimize) for citizens at the given coordinates.
/// Note: Backend defines citizen_scenario_actions route taking query parameters lat & lon.
Future<Map<String, dynamic>?> fetchCitizenActions({
  required double lat,
  required double lon,
}) async {
  try {
    final uri = Uri.parse('$baseURL/citizen_actions?lat=$lat&lon=$lon');
    final response = await http.post(
      uri,
      headers: {'Content-Type': 'application/json'},
    ).timeout(_llmTimeout);

    if (response.statusCode == 200) {
      final data = json.decode(response.body);
      if (data is Map<String, dynamic>) {
        ApiCache.save(ApiCache.coordKey('actions', lat, lon), data);
        return data;
      } else {
        throw Exception('Expected Map response, got ${data.runtimeType}');
      }
    } else {
      throw Exception('Failed to load citizen actions (${response.statusCode}): ${response.body}');
    }
  } catch (e) {
    print('API Error (fetchCitizenActions): $e');
    rethrow;
  }
}

